'use client';

import { Combobox as ComboboxPrimitive } from '@base-ui/react';
import { CheckIcon, ChevronsUpDown, SearchIcon } from 'lucide-react';
import { cn } from '@/lib/utils';

const McCombobox = ComboboxPrimitive.Root;

function McComboboxValue({ ...props }: ComboboxPrimitive.Value.Props) {
  return <ComboboxPrimitive.Value data-slot="combobox-value" {...props} />;
}

function McComboboxTrigger({
  className,
  placeholder,
  ...props
}: ComboboxPrimitive.Trigger.Props & { placeholder?: string }) {
  return (
    <ComboboxPrimitive.Trigger
      data-slot="combobox-trigger"
      className={cn(
        'min-w-50 min-h-9 px-3 py-2 rounded-md ring-1 ring-inset ring-border shadow-xs flex justify-between items-center bg-input text-foreground paragraph-sm font-medium',
        className
      )}
      {...props}
    >
      <McComboboxValue placeholder={placeholder} />
      <ChevronsUpDown className="size-4 text-foreground" />
    </ComboboxPrimitive.Trigger>
  );
}

function McComboboxSearch({
  className,
  placeholder,
  ...props
}: ComboboxPrimitive.Input.Props & { placeholder?: string }) {
  return (
    <div className="flex items-center border-b px-3 h-fit w-full gap-2" data-slot="combobox-search">
      <SearchIcon className="text-muted-foreground size-4" />
      <ComboboxPrimitive.Input
        className={cn(
          'flex h-10 w-full rounded-md bg-transparent py-3 outline-none paragraph-sm placeholder:text-muted-foreground',
          className
        )}
        placeholder={placeholder}
        {...props}
      />
    </div>
  );
}

function McComboboxContent({
  className,
  side = 'bottom',
  sideOffset = 8,
  align = 'start',
  ...props
}: ComboboxPrimitive.Popup.Props &
  Pick<ComboboxPrimitive.Positioner.Props, 'side' | 'align' | 'sideOffset'>) {
  return (
    <ComboboxPrimitive.Portal>
      <ComboboxPrimitive.Positioner
        side={side}
        sideOffset={sideOffset}
        align={align}
        className="isolate z-50"
      >
        <ComboboxPrimitive.Popup
          data-slot="combobox-content"
          className={cn(
            'w-[var(--anchor-width)] flex flex-col rounded-md ring-1 ring-inset ring-border bg-card-background shadow-md',
            className
          )}
          {...props}
        />
      </ComboboxPrimitive.Positioner>
    </ComboboxPrimitive.Portal>
  );
}

function McComboboxList({ className, ...props }: ComboboxPrimitive.List.Props) {
  return (
    <ComboboxPrimitive.List
      data-slot="combobox-list"
      className={cn('p-1 h-fit w-full', className)}
      {...props}
    />
  );
}

function McComboboxItem({ className, children, ...props }: ComboboxPrimitive.Item.Props) {
  return (
    <ComboboxPrimitive.Item
      data-slot="combobox-item"
      className={cn(
        'relative flex w-full rounded py-1.5 px-2 gap-2 justify-between paragraph-sm items-center',
        'data-highlighted:bg-accent data-highlighted:text-accent-foreground',
        className
      )}
      {...props}
    >
      {children}
      <ComboboxPrimitive.ItemIndicator>
        <CheckIcon className="size-4 text-accent-foreground" />
      </ComboboxPrimitive.ItemIndicator>
    </ComboboxPrimitive.Item>
  );
}

export {
  McCombobox,
  McComboboxTrigger,
  McComboboxSearch,
  McComboboxContent,
  McComboboxList,
  McComboboxItem,
  McComboboxValue,
};
